package dev.pocketengine.features.assistant.notifications;

import android.Manifest;import android.app.*;import android.content.*;import android.database.sqlite.SQLiteDatabase;import android.service.notification.StatusBarNotification;
import dev.pocketengine.core.RunControl;import dev.pocketengine.store.TaskStore;import java.util.*;import java.util.concurrent.atomic.*;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import static org.junit.Assert.*;

/** Actual original SQL, Android NotificationManager/PendingIntent and read-only native navigation. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=Application.class) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class AssistantTaskNotificationsNativeTest {
 private static final class Fixture implements AutoCloseable {
  final Application app=RuntimeEnvironment.getApplication();final TaskStore tasks;final NotificationManager manager=app.getSystemService(NotificationManager.class);final JSONObject task;final String id,run;final int epoch;final RunControl original=new RunControl();
  Fixture()throws Exception{app.deleteDatabase("pocket-world.db");tasks=new TaskStore(app);manager.cancelAll();Shadows.shadowOf(manager).setNotificationsEnabled(true);Shadows.shadowOf(app).grantPermissions(Manifest.permission.POST_NOTIFICATIONS);task=tasks.startAttempt(tasks.createCapabilityTask("SENSITIVE-OWNER-TEXT",UUID.randomUUID().toString()).getString("id"),"capabilities",8);id=task.getString("id");run=task.getString("runId");epoch=task.getInt("coordinatorEpoch");original.bindHostRun(id,run,epoch);}
  void end(String status)throws Exception{tasks.endAttempt(id,run,status,"SECRET-MODEL-RESULT",new JSONObject());}
  public void close()throws Exception{manager.cancelAll();var field=TaskStore.class.getDeclaredField("db");field.setAccessible(true);((SQLiteDatabase)field.get(tasks)).close();}
 }
 @Test public void notificationIsNotPlannedBeforeActualRunAndCleanupHaveEnded()throws Exception{try(Fixture f=new Fixture()){
  f.tasks.status(f.id,"needs_confirmation","model result arrived but cleanup still running");assertNull(f.tasks.ownerTaskNotice(f.id));assertEquals(0,f.manager.getActiveNotifications().length);f.end("needs_confirmation");TaskStore.OwnerTaskNotice claim=f.tasks.ownerTaskNotice(f.id);assertNotNull(claim);assertEquals(f.run,claim.view().getString("runId"));assertFalse(claim.view().getBoolean("executionAuthorized"));
 }}
 @Test public void atomicPostingClaimPreventsDuplicateConcurrentPostingAndLatePostedCannotUndoOpened()throws Exception{try(Fixture f=new Fixture()){
  f.end("needs_confirmation");var one=f.tasks.ownerTaskNotice(f.id);var two=f.tasks.ownerTaskNotice(f.id);assertNotNull(one);assertNotNull(two);assertTrue(f.tasks.beginOwnerTaskNoticePosting(one));assertFalse(f.tasks.beginOwnerTaskNoticePosting(two));JSONObject view=one.view();f.tasks.openOwnerTaskNotice(f.id,f.run,f.epoch,view.getString("token"));f.tasks.ownerTaskNoticePhase(one,"posted");assertEquals("opened",f.tasks.get(f.id,false).getJSONObject("ownerNotification").getString("phase"));assertNull(f.tasks.ownerTaskNotice(f.id));assertFalse(f.original.isCancelled());
 }}
 @Test public void realResultNotificationOpensOnlyOriginalRecordAndRepeatedUpdatesNeverPostAgain()throws Exception{try(Fixture f=new Fixture()){
  f.end("needs_confirmation");AssistantTaskNotifications delivery=new AssistantTaskNotifications(f.app,f.tasks);delivery.update(f.id);StatusBarNotification[] posted=f.manager.getActiveNotifications();assertEquals(1,posted.length);Notification n=posted[0].getNotification();assertFalse(n.extras.toString().contains("SENSITIVE"));assertFalse(n.extras.toString().contains("SECRET"));assertTrue(n.contentIntent.isImmutable());assertTrue(n.actions==null||n.actions.length==0);String beforeRun=f.tasks.get(f.id,false).getString("runId");int beforeOperations=f.tasks.get(f.id,false).getJSONArray("operations").length();
  delivery.update(f.id);assertEquals(1,f.manager.getActiveNotifications().length);n.contentIntent.send();Intent open=Shadows.shadowOf(f.app).getNextStartedActivity();assertNotNull(open);AtomicReference<JSONObject> focus=new AtomicReference<>();AtomicInteger warnings=new AtomicInteger();assertTrue(AssistantTaskNotifications.openRequestedTask(f.tasks,open,focus::set,message->warnings.incrementAndGet()));assertEquals(f.id,focus.get().getString("taskId"));assertFalse(focus.get().getBoolean("executionAuthorized"));assertFalse(focus.get().getBoolean("expired"));assertEquals(0,warnings.get());assertEquals(beforeRun,f.tasks.get(f.id,false).getString("runId"));assertEquals(beforeOperations,f.tasks.get(f.id,false).getJSONArray("operations").length());assertFalse(f.original.isCancelled());assertEquals("opened",f.tasks.get(f.id,false).getJSONObject("ownerNotification").getString("phase"));assertNull(open.getAction());assertFalse(AssistantTaskNotifications.openRequestedTask(f.tasks,open,focus::set,message->warnings.incrementAndGet()));
 }}
 @Test public void oldNoticeCannotResumeOrClearAReplacementRunOrItsNewNotification()throws Exception{try(Fixture f=new Fixture()){
  f.end("needs_confirmation");JSONObject old=f.tasks.ownerTaskNotice(f.id).view();f.tasks.ownerTaskNoticePhase(f.tasks.ownerTaskNotice(f.id),"posted");JSONObject newer=f.tasks.startAttempt(f.id,"capabilities",8);f.tasks.endAttempt(f.id,newer.getString("runId"),"awaiting_user","newer owner decision",new JSONObject());JSONObject current=f.tasks.ownerTaskNotice(f.id).view();assertNotEquals(old.getString("token"),current.getString("token"));
  JSONObject opened=f.tasks.openOwnerTaskNotice(f.id,f.run,f.epoch,old.getString("token"));assertTrue(opened.getBoolean("expired"));assertEquals(newer.getString("runId"),opened.getString("runId"));assertEquals(current.getString("token"),f.tasks.get(f.id,false).getJSONObject("ownerNotification").getString("token"));assertEquals("planned",f.tasks.get(f.id,false).getJSONObject("ownerNotification").getString("phase"));assertEquals("awaiting_user",f.tasks.get(f.id,false).getString("status"));assertEquals(0,f.tasks.get(f.id,false).getJSONArray("operations").length());
 }}
 @Test public void deniedNotificationPermissionIsVisibleWithoutPretendingDeliveryOrRerunningTask()throws Exception{try(Fixture f=new Fixture()){
  f.end("reconciling");Shadows.shadowOf(f.app).denyPermissions(Manifest.permission.POST_NOTIFICATIONS);AssistantTaskNotifications delivery=new AssistantTaskNotifications(f.app,f.tasks);delivery.update(f.id);JSONObject retained=f.tasks.get(f.id,false);assertEquals("permission_required",retained.getJSONObject("ownerNotification").getString("phase"));assertFalse(retained.getJSONObject("ownerNotification").getBoolean("deliveryConfirmed"));assertEquals(0,f.manager.getActiveNotifications().length);assertEquals("reconciling",retained.getString("status"));assertEquals(0,retained.getJSONArray("operations").length());assertFalse(f.original.isCancelled());
  Shadows.shadowOf(f.app).grantPermissions(Manifest.permission.POST_NOTIFICATIONS);delivery.update(f.id);assertEquals(1,f.manager.getActiveNotifications().length);assertFalse(f.tasks.get(f.id,false).getJSONObject("ownerNotification").getBoolean("deliveryConfirmed"));
 }}
}
